def split_ict(apps, schema_editor):
    Subject = apps.get_model("curriculum", "Subject")
    Unit = apps.get_model("curriculum", "Unit")
    Lesson = apps.get_model("curriculum", "Lesson")
    Resource = apps.get_model("curriculum", "Resource")
    Question = apps.get_model("assessments", "Question")
    Quiz = apps.get_model("assessments", "Quiz")
    with_unit = (Question, Quiz, Resource)

    ict = Subject.objects.filter(code="ict").first()
    if ict is None:
        return  # a new installation: load_curriculum creates both subjects
    if ict.name == "ICT & Computer Science":
        ict.name, ict.name_fr = "ICT", "TIC"
        ict.save(update_fields=["name", "name_fr"])
    cs, _ = Subject.objects.get_or_create(
        code="computer-science",
        defaults={
            "name": "Computer Science",
            "name_fr": "Informatique",
            "category": "computer-science",
            "icon": "cpu",
            "color": "#4F46E5",
            "offered_o_level": False,
            "offered_a_level": True,
            "order": ict.order + 1,
        },
    )
    subjects = {"ict": (ict, ICT_TITLES), "computer-science": (cs, CS_TITLES)}

    found = []
    for grade, rows in OLD_ICT_UNITS.items():
        for number, (title, target) in enumerate(rows, start=1):
            # Matched by title too: a unit an admin renamed, or one already on the new outline, stays put.
            unit = Unit.objects.filter(subject=ict, grade=grade, number=number, title=title).first()
            if unit is not None:
                found.append((unit, target))
    # Park them first: their new numbers are still taken by other old units.
    for parked, (unit, _) in enumerate(found, start=900):
        unit.number = parked
        unit.save(update_fields=["number"])

    for unit, target in found:
        if target is None:
            holds_work = Lesson.objects.filter(unit=unit).exists() or any(
                model.objects.filter(unit=unit).exists() for model in with_unit
            )
            if not holds_work:
                unit.delete()
                continue
            taken = set(Unit.objects.filter(subject=ict, grade=unit.grade).values_list("number", flat=True))
            unit.number = next(n for n in range(NEW_ICT_UNIT_COUNT[unit.grade] + 1, 900) if n not in taken)
            unit.save(update_fields=["number"])
            continue
        code, number = target
        subject, titles = subjects[code]
        title, title_fr = titles[(unit.grade, number)]
        there = Unit.objects.filter(subject=subject, grade=unit.grade, number=number).first()
        if there is not None:  # another old unit moved here already (or the unit exists): merge into it
            Lesson.objects.filter(unit=unit).update(unit=there)
            for model in with_unit:
                model.objects.filter(unit=unit).update(unit=there)
            unit.delete()
        else:
            if unit.title != title:
                unit.alignment_verified = False  # a new title must be checked again
            unit.subject, unit.number, unit.title, unit.title_fr = subject, number, title, title_fr
            unit.save()
            there = unit
        # Questions, quizzes and books keep their own subject: it follows the unit into Computer Science.
        for model in with_unit:
            model.objects.filter(unit=there).exclude(subject=subject).update(subject=subject)


